-- استيراد بيانات ميدانية حقيقية من منصة "سند" (Quanta Club)
-- المصدر: https://sanad-ca736.web.app  —  يُنسب الفضل لهم في جمع هذه البيانات.
--
-- تم استبعاد 5 جمعيات وردت في المصدر بأرقام هاتف ذات نمط تسلسلي واضح
-- (0550123456 / 0661234567 / 0558765432 / 0799887766 / 0771892345) لأنها على الأرجح
-- أرقام نموذجية وليست حقيقية. لا تُنشر أرقام غير مؤكدة في منصة إغاثة.
-- الجمعيات المستبعدة: نبض الخير، بصمة خير، سواعد الإحسان، الغيث القوافلية، الفجر التضامنية.
-- يمكن إضافتها لاحقًا من لوحة الإدارة فور تأكيد أرقامها ميدانيًا.

do $$
declare
  v_campaign_id uuid;
  v_src text := 'مصدر البيانات: منصة سند (Quanta Club) — sanad-ca736.web.app';
  z record;
  v_cat_id uuid;
begin
  select id into v_campaign_id from public.campaigns where slug = 'jijel-fires-2026';

  ---------------------------------------------------------------- مراكز الإيواء
  insert into public.relief_hubs (
    campaign_id, name, wilaya, commune, address, lat, lng, phone,
    show_phone_publicly, capacity_note, is_shelter, status, verification_level, notes
  ) values
  (v_campaign_id,'مركز التكوين المهني بوهراوة أحمد (CFPA)','جيجل','الشقفة','الشقفة مركز، محاذاة الطريق الرئيسي',36.77237,5.95213,'034 56 21 52',true,'مجهز لاستقبال العائلات • دورات مياه وأفرشة',true,'open','verified',v_src),
  (v_campaign_id,'دار الشباب الشهيد بوناب الرشيد','جيجل','جيجل','حي الفرسان، بن شعبان',36.8120,5.7720,'034 47 43 75',true,'استقبال وفرز القوافل الوطنية وتوجيهها',true,'open','verified',v_src),
  (v_campaign_id,'مركب الشباب الشهيد شاطر عبد القادر','جيجل','جيجل','حي 1000 مسكن، جيجل',36.8180,5.7650,'030 49 08 22',true,'مجمع شبابي مجهز للإيواء المؤقت والرعاية',true,'open','verified',v_src),
  (v_campaign_id,'ديوان مؤسسات الشباب (ODEJ)','جيجل','جيجل','وسط مدينة جيجل',36.8120,5.7660,'034 47 43 75',true,'خلية التنسيق الولائية للمؤسسات الشبانية',false,'open','verified',v_src),
  (v_campaign_id,'مركز استقبال ومأوى تاكسنة','جيجل','تاكسنة','بلدية تاكسنة مركز',36.6667,5.7833,'034 49 10 20',true,'استقبال 65+ حالة وإسعاف الأسر المتضررة',true,'open','verified',v_src),
  (v_campaign_id,'مركز إيواء العرايب','جيجل','الميلية','منطقة العرايب، طريق برج العنصر',36.7500,6.2667,'034 52 11 22',true,'مخيم استقبال وإيواء للأسر المُجلية من تنفدور',true,'open','verified',v_src),
  (v_campaign_id,'مقر بلدية بوراوي بلهادف (APC)','جيجل','بوراوي بلهادف','مقر المجلس الشعبي البلدي',36.6167,5.9500,'034 46 51 68',true,'نقطة استقبال وتوجيه المساعدات للمداشر الجبلية',false,'open','verified',v_src);

  ------------------------------------------------------------ نقاط التجميع / الجمعيات
  -- فقط الجمعيات ذات أرقام الهاتف المؤكدة
  insert into public.collection_points (
    campaign_id, name, wilaya, commune, address, phone, show_phone_publicly,
    accepted_categories, capacity_note, status, verification_level, notes
  ) values
  (v_campaign_id,'جمعية خاوة فالخير – جيجل','جيجل','جيجل','حي الكريط، قرب صيدلية نخول','0744160656',true,
    array['food','water','relief_materials'],'خلية أزمة وإمداد غذائي — جمع التبرعات العينية والغذائية وتوجيهها للقرى الجبلية','open','verified',v_src),
  (v_campaign_id,'جمعية الياقوت الأزرق الثقافية','جيجل','جيجل','حي الفرسان – بن شعبان','034 47 43 75',true,
    array['food','clothing','blankets','hygiene','relief_materials'],'نقطة استقبال وفرز — استقبال مساهمات المواطنين وتنسيق توزيعها','open','verified',v_src),
  (v_campaign_id,'جمعية نور للناس – جيجل','جيجل','جيجل','فوبور، وسط جيجل','0770999153',true,
    array['medical','food'],'مستلزمات طبية وأدوية — شراء واستقبال المستلزمات الطبية والأدوية العاجلة','open','verified',v_src),
  (v_campaign_id,'جمعية نجدة الإنسانية للصحة والإغاثة','جيجل','جيجل','فرع ولاية جيجل','0541600236',true,
    array['medical'],'إغاثة صحية وإسعافات — قوافل طبية ورعاية صحية ميدانية','open','verified',v_src),
  (v_campaign_id,'جمعية قوافل الخير (بني حبيبي)','جيجل','الجمعة بني حبيبي','شارع عوار حسين، بني حبيبي','0551444192',true,
    array['food','blankets','relief_materials'],'تنسيق ريفي وتوزيع مباشر — شبكة تواصل مع عائلات المشاتي والقرى المتضررة','open','verified',v_src);

  ------------------------------------------------------- الاحتياجات (المناطق الحرجة)
  for z in
    select * from (values
      ('الجمعة بني حبيبي','critical','المناطق السكنية، مشاتي الشارع الرئيسي والمحيط الغابي','أولوية إنسانية قصوى؛ تأكد من احتياج الأسر المسجلة محليًا قبل إرسال الشحنات.',
        array['water','baby_supplies','blankets','food'], array['مياه معقمة','حليب وحفاضات أطفال','أفرشة وبطانيات','طرود غذائية']),
      ('تاكسنة','high','بوخلف، بوزنطار، الرازيانج، الغريانة، أم ثلاثين، الكلم 14','مسالك جبلية وعرة؛ تتطلب مركبات دفع رباعي وشاحنات صغيرة محلية (توزيع آخر ميل).',
        array['other','shelter','hygiene'], array['مركبات 4x4 للتوزيع وأعلاف للمواشي','خيام وقياطين','أدوات تنظيف ومجارف']),
      ('زيامة منصورية','high','أولاد علي، الشريعية، محيط تازة والكهوف العجيبة','تضاريس ومنعطفات وعرة؛ لا تعتمد على الشاحنات الكبيرة وحدها لدخول القرى.',
        array['water','kitchenware','blankets','hygiene'], array['مياه صالحة للشرب','أواني وأدوات طبخ','أفرشة','مواد تعقيم']),
      ('الشقفة','high','منطقة السبت، محيط الشقفة وبرج الطهر، المداشر الغابية','الأفرشة والبطانيات وأدوات التنظيف ومياه الشرب أهم حاليًا من تكرار المواد الغذائية.',
        array['blankets','hygiene','other','water'], array['أفرشة وبطانيات','أدوات تنظيف ومكانس','خراطيم ودلاء','مياه نقية']),
      ('الميلية','high','مشاط، بوعقبة والمناطق الغابية المحيطة','مركز استقبال رئيسي للقوافل الشرقية؛ التوجيه للمداشر الغابية عبر شاحنات صغيرة.',
        array['construction_materials','other','food','medical'], array['أدوات سباكة وكهرباء','مضخات مياه','طرود غذائية','دعم صحي']),
      ('العنصر','medium','مناطق متفرقة ظهرت في عمليات الإجلاء الميداني','بيانات مجمّعة — يجب التأكد بالتواصل مع الجهة المُنسّقة قبل التحرك.',
        array['blankets','food','hygiene'], array['أفرشة','طرود غذائية','أدوات تنظيف'])
    ) as t(commune, prio, places, advice, cats, labels)
  loop
    for i in 1 .. array_length(z.cats, 1) loop
      select id into v_cat_id from public.categories where slug = z.cats[i];
      insert into public.needs (
        campaign_id, category_id, wilaya, commune, title,
        quantity_needed, quantity_available, unit, priority, status,
        source_type, verification_level, notes
      ) values (
        v_campaign_id, v_cat_id, 'جيجل', z.commune, z.labels[i],
        0, 0, 'piece', z.prio::public.priority_level, 'active',
        'field_team', 'verified',
        z.places || ' — ' || z.advice || ' | ' || v_src
      );
    end loop;
  end loop;
end $$;
